package org.springframework.samples.petclinic.acceptance;

import org.junit.jupiter.api.Test;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import tools.jackson.databind.node.ObjectNode;

/** contact-preference: Return 'contactPreference' = 'EMAIL' when an email is present, otherwise 'PHONE'.... */
class AcceptanceTest extends AcceptanceBase {

	@Test
	void corePhoneWhenNoEmail() throws Exception {
		int id = createOwnerOk(ownerNode());
		getOwner(id).andExpect(jsonPath("$.contactPreference").value("PHONE"));
	}

	@Test
	void functionalityEmailWhenPresent() throws Exception {
		ObjectNode o = ownerNode();
		o.put("email", uniqueEmail());
		int id = createOwnerOk(o);
		getOwner(id).andExpect(jsonPath("$.contactPreference").value("EMAIL"));
	}
}

content.content:
          minLength: 1
          maxLength: 255
          example: '110 W. Liberty St.'
        city:
          title: City
          description: The city of the pet owner.
          type: string
          minLength: 1
          maxLength: 80
          example: Madison
        telephone:
          title: Telephone number
          description: >-
            The telephone number of the pet owner, stored and returned in E.164 form. Spaces,
            dashes and brackets are removed. A leading '+' and country code are kept; otherwise
            a single leading '0' is dropped and country code '+61' is assumed. Between 8 and 15
            digits must follow the '+', e.g. '0412 345 678' is stored as '+61412345678'. Numbers
            with country code '+61' must have exactly 9 national digits and numbers with country
            code '+1' exactly 10.
          type: string
          minLength: 1
          maxLength: 20
          example: '+61412345678'
        email:
          title: Email address
          description: >-
            The optional email address of the pet owner. When present it must be a syntactically
            valid address; it is stored and returned lower-cased.
          type: string
          format: email
          maxLength: 255
          example: 'george.franklin@example.com'
        registrationDate:
          title: Registration date
          description: >-
            The date the owner registered with the clinic. On create, when omitted it defaults to
            the server's current date. A Saturday or Sunday (supplied or defaulted) is rolled
            forward to the following Monday.
          type: string
